content.content:
name: everbloom
description: "A new DartNative project."
publish_to: 'none'
version: 0.1.0+1

environment:
  sdk: ^3.12.0-192.0.dev

# Plain version deps: `dn pub get` resolves DartNative packages from your
# installed SDK (closed resolution) — no registry setup, works offline.
dependencies:
  dartnative: ^1.0.0
  dartnative_ios: ^1.0.0
  dartnative_android: ^1.0.0
  # Skia GPU canvas: SkSL runtime shaders and rich shaped text. Adds about
  # 9 MB to an iPhone app; on Android the library is already in the platform
  # binding. For shapes, paths and charts use CustomPaint, which is native
  # and free. Uncomment here, then in lib/main.dart:
  #
  #   import 'package:dartnative_skia/dartnative_skia.dart';
  #
  #   void main() {
  #     DartNativePluginRegistrant.registerAll();
  #     registerSkiaFactories();          // without this a CanvasSurface throws
  #     runApp(const HomeScreen());
  #   }
  #
  # dartnative_skia: ^1.0.0

dev_dependencies:
  lints: ^6.0.0
  image: ^4.0.0
  test: ^1.25.0

# Which Skia binary ships with the app. Pick one; see the Skia page.
#
#   bare  canvas, SkSL shaders and Latin text        about 4 MB on iPhone
#   full  bare, plus shaped text drawn inside a      about 9 MB on iPhone
#         Skia canvas: Arabic, CJK, right-to-left
#
# dartnative_skia:
#   variant: bare
#   # variant: full

dartnative:
  assets:
    - assets/dn-logo.png

# Branded launch splash + app icon: add the dartnative_splash plugin from
# dartpub.dev, then see tool/generate_app_assets.dart.
import 'package:dartnative/dartnative.dart';

import 'dartnative_plugin_registrant.dart';

void main() {
  // Platform bindings + (once you add plugins) their FFI symbols. Keep this
  // as the FIRST line of main() — see lib/dartnative_plugin_registrant.dart.
  DartNativePluginRegistrant.registerAll();
  // App-wide system chrome default for the white template: dark status-bar
  // icons over the light background, transparent strips. Screens can override
  // in initState; the navigator restores this default on pop.
  SystemChrome.defaultStyle = const SystemUiOverlayStyle(
    statusBarColor: Colors.transparent,
    statusBarBrightness: Brightness.light,
    statusBarIconBrightness: Brightness.dark,
    systemNavigationBarColor: Colors.transparent,
    systemNavigationBarIconBrightness: Brightness.dark,
  );
  runApp(const HomeScreen());
}

/// Starter screen — replace this with your own UI.
class HomeScreen extends StatelessWidget {
  const HomeScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      // White-by-design screen: declare the light trait so system materials
      // (keyboard, glass) stay light even when the device is in Dark Mode.
      brightness: Brightness.light,
      appBar: AppBar(
        title: const Text('DartNative'),
        // No backgroundColor: on iOS 26 this is the fully CLEAR glass bar
        // (the system scroll-edge ramp keeps it legible); elsewhere the
        // platform's default light bar over the white screen.
      ),
      backgroundColor: const Color(0xFFFFFFFF),
      body: Container(
        alignment: Alignment.center,
        padding: const EdgeInsets.all(32),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: const [
            Text(
              '👋  Welcome to DartNative',
              textAlign: TextAlign.center,
              style: TextStyle(fontSize: 20),
            ),
            SizedBox(height: 10),
            Text(
              'Edit lib/main.dart to build your app. '
              'See README.md to swap the app icon / splash logo, '
              'and dartpub.dev for plugins.',
              textAlign: TextAlign.center,
            ),
          ],
        ),
      ),
    );
  }
}
