// The auto-start machine free-access trial, against dartpub's live contract
// (MESSAGE_FROM_DARTPUB_1 §1, finalized in MESSAGE_FROM_DARTPUB_3).
//
// `POST /trial/begin` is both "start my trial" and the idempotent daily
// re-check: the server keeps ONE row per machine_hash and re-mints the same
// window, so calling it again is always safe. The server also owns every word
// the developer reads: the response's `notice` is either a line to print
// VERBATIM or null meaning print NOTHING. The tool never composes trial or
// subscribe wording, and never prints a number of days — `trial_days` and
// `expires_at` drive internal timing only.
//
// Offline (or any non-committal server answer): print nothing and keep
// working from the stored token. A 4xx is different — a policy refusal, not a
// network failure — and its `message` is printed verbatim.
//
// Subscriber tokens (`dn config --license-key` / --dart-define) bypass all of
// this. The compiled public demo token remains for INTERNAL/CI use only,
// behind DN_INTERNAL_DEMO_TOKEN=1 — it must never auto-inject for developers,
// or it bypasses the trial.

import 'dart:async';
import 'dart:convert';
import 'dart:io' as io;

import 'package:crypto/crypto.dart' show sha256;
import 'package:meta/meta.dart';
import 'package:process/process.dart';

import 'base/context.dart';
import 'base/error_handling_io.dart';
import 'base/file_system.dart';
import 'dartnative_demo_token.dart';
import 'globals.dart' as globals;

/// Fixed client salt for the machine hash — an opacity measure (the server
/// only ever sees SHA-256(machine id + salt)), not a secret.
const String _kMachineHashSalt = 'dartnative-trial-v3';

const String _kTrialApiBaseDefault = 'https://api.dartpub.dev';

/// Environment override for the trial API base (local/E2E testing).
const String _kTrialApiBaseEnv = 'DN_TRIAL_API_BASE';

/// Internal/CI escape hatch: inject the compiled public demo token instead of
/// the machine trial. Never documented for developers.
const String _kInternalDemoEnv = 'DN_INTERNAL_DEMO_TOKEN';

/// How often the tool re-asks the server (the "daily re-check").
const Duration _kRecheckInterval = Duration(hours: 24);

String get _trialApiBase =>
    globals.platform.environment[_kTrialApiBaseEnv] ?? _kTrialApiBaseDefault;

Directory _stateDir() {
  final String home = globals.platform.environment['HOME'] ??
      globals.platform.environment['USERPROFILE'] ??
      '.';
  return globals.fs.directory(globals.fs.path.join(home, '.dartnative'));
}

/// The stored trial state (token + server metadata + when we last heard back).
File _stateFile() => _stateDir().childFile('trial.json');

/// Pre-contract storage: the raw token alone. Read as a fallback, removed once
/// a successful check writes trial.json.
File _legacyTokenFile() => _stateDir().childFile('trial_token');

/// The trial token to inject for this run, or null when none should be
/// injected (access ended, server refused, or nothing stored and the server is
/// unreachable). Prints the server's `notice` (or a refusal `message`)
/// verbatim as a side effect — and prints nothing otherwise.
///
/// Memoized for the process lifetime: `getBuildInfo()` re-assembles the
/// dart-defines several times per command, and without this a notice would
/// print (and a failed fetch would retry) once per call.
Future<String?> dartNativeTrialToken() {
  final DartNativeTrialStandIn? standIn = context.get<DartNativeTrialStandIn>();
  if (standIn != null) {
    _trialEnded = standIn.ended;
    return Future<String?>.value(standIn.token);
  }
  return _tokenOnce ??= _dartNativeTrialToken();
}
Future<String?>? _tokenOnce;

/// What the trial answers in tests, in place of the developer's stored trial
/// state and the licence server.
///
/// Only the test harness registers one (test/src/context.dart), so that no
/// test reads the trial file in the real home folder or contacts the server,
/// and every test build carries the same licence on every machine. The tool
/// never registers it; the trial's own tests turn it off.
@visibleForTesting
class DartNativeTrialStandIn {
  const DartNativeTrialStandIn({this.token, this.ended = false});

  /// The trial token a build carries, or null for none.
  final String? token;

  /// Whether the server has said the free access has ended.
  final bool ended;
}

/// Whether the server has said this machine's free access has ended, as
/// opposed to the other reasons there might be no token (never started,
/// server unreachable, refused). Only meaningful after [dartNativeTrialToken]
/// has completed.
///
/// The app it builds cannot tell these apart by itself — it just finds no
/// licence — so the tool passes this on (as a dart-define, never the console).
bool get dartNativeTrialEnded => _trialEnded;
bool _trialEnded = false;

/// Whether the server refused this machine's trial AND said why in its own
/// words, which [_beginTrial] has already printed verbatim.
///
/// The caller uses this to stay quiet: the server owns every word a
/// developer reads about the trial, so a second line composed here would
/// talk over a policy decision that has already been explained.
bool get dartNativeTrialRefusedWithMessage => _refusedWithMessage;
bool _refusedWithMessage = false;

/// Clears the process-lifetime memoization so each test starts fresh.
@visibleForTesting
void resetDartNativeTrialForTesting() {
  _tokenOnce = null;
  _trialEnded = false;
  _refusedWithMessage = false;
}

Future<String?> _dartNativeTrialToken() async {
  if (globals.platform.environment[_kInternalDemoEnv] == '1') {
    return kDartNativeDemoToken; // internal/CI only
  }

  final _TrialState? stored = _readState();
  final int now = _nowEpochSeconds();

  final bool due = stored == null ||
      now - stored.checkedAt >= _kRecheckInterval.inSeconds ||
      (stored.state == _TrialState.kActive && now >= stored.expiresAt);

  if (!due) {
    if (stored.state == _TrialState.kEnded) {
      _trialEnded = true;
      return null;
    }
    return stored.token; // active and inside the window — silence.
  }

  final _BeginOutcome outcome = await _beginTrial();
  switch (outcome.kind) {
    case _BeginKind.answered:
      final _TrialState fresh = outcome.state!;
      if (fresh.state == _TrialState.kEnded) {
        _trialEnded = true;
        return null;
      }
      return fresh.token;
    case _BeginKind.refused:
      // A policy decision: its message (if any) was printed verbatim by
      // _beginTrial. Nothing is injected this run; stored state is untouched
      // so a later policy change can revive it on the next check.
      return null;
    case _BeginKind.unreachable:
      // Offline (or a non-committal answer): print nothing and keep working
      // from the stored token. Never invent text, never re-print a remembered
      // notice.
      if (stored == null) {
        return _readLegacyToken();
      }
      if (stored.state == _TrialState.kEnded) {
        _trialEnded = true;
        return null;
      }
      if (now >= stored.expiresAt) {
        // The stored window has lapsed but the server never told us "ended"
        // (it may have extended the row). Inject nothing, claim nothing.
        return null;
      }
      return stored.token;
  }
}

/// Status for `dn trial` — never fetches, never injects, and (per the dartpub
/// contract) never states a number of days or composes subscribe wording.
String dartNativeTrialStatusText() {
  final _TrialState? stored = _readState();
  if (stored == null) {
    if (_readLegacyToken() != null) {
      return 'Free access on this machine is due a check with the server — '
          'it refreshes the next time you run an official demo.';
    }
    return 'Free access has not started yet.\n'
        'It starts automatically the first time you run an official demo or '
        'plugin example — no account, no key.';
  }
  if (stored.state == _TrialState.kEnded) {
    return 'Your free access has ended.';
  }
  if (_nowEpochSeconds() >= stored.expiresAt) {
    return 'Free access on this machine is due a check with the server — '
        'it refreshes the next time you run an official demo.';
  }
  return 'Free access is active on this machine — every official demo and '
      'plugin example is unlocked.';
}

enum _BeginKind { answered, refused, unreachable }

class _BeginOutcome {
  const _BeginOutcome(this.kind, [this.state]);
  final _BeginKind kind;
  final _TrialState? state;
}

/// POST /trial/begin with the anonymous machine hash.
///
/// 200 → print `notice` verbatim when non-null (nothing when null), persist
/// the state, return it. 4xx → a policy refusal: print its `message`
/// verbatim, return refused. Anything else (network error, 5xx, malformed
/// body) → print nothing, return unreachable.
Future<_BeginOutcome> _beginTrial() async {
  final io.HttpClient client =
      (globals.httpClientFactory ?? () => io.HttpClient())();
  client.connectionTimeout = const Duration(seconds: 10);
  try {
    final io.HttpClientRequest req =
        await client.postUrl(Uri.parse('$_trialApiBase/trial/begin'));
    req.headers.contentType = io.ContentType.json;
    req.write(json.encode(<String, String>{'machine_hash': _machineHash()}));
    final io.HttpClientResponse res = await req.close();
    final String body = await utf8.decodeStream(res);
    if (res.statusCode == 200) {
      final answer = json.decode(body) as Map<String, Object?>;
      final notice = answer['notice'] as String?;
      if (notice != null) {
        globals.printStatus(notice); // verbatim — the server's words, exactly.
      }
      final state = _TrialState(
        token: answer['token']! as String,
        expiresAt: answer['expires_at']! as int,
        trialDays: answer['trial_days']! as int,
        state: answer['state']! as String,
        checkedAt: _nowEpochSeconds(),
      );

