library;

import 'dart:async';
import 'dart:convert';
import 'dart:ffi';
import 'dart:io';
import 'dart:math';

import 'package:ffi/ffi.dart';

import 'package:dartnative/src/license/_sha256.dart';

enum LicenseStatus {

  valid,

  expired,

  missing,

  invalid,
}

class LicensePayload {

  final String sub;

  final String email;

  final String plan;

  final String? orgId;

  final String machineId;

  final int exp;

  final int offlineUntil;

  final List<String> plugins;

  final List<String> thirdPartyPlugins;

  final String? jti;

  final int iat;

  final List<String>? apps;

  const LicensePayload({
    required this.sub,
    required this.email,
    required this.plan,
    this.orgId,
    required this.machineId,
    required this.exp,
    required this.offlineUntil,
    required this.plugins,
    required this.thirdPartyPlugins,
    required this.iat,
    this.jti,
    this.apps,
  });

  factory LicensePayload.fromJson(Map<String, dynamic> json) { throw UnimplementedError(); }

  Map<String, dynamic> toJson() { throw UnimplementedError(); }

  bool get isExpired { throw UnimplementedError(); }

  bool get isOfflineExpired { throw UnimplementedError(); }
}

class UpdatePrompt {

  final String? storeUrl;

  final void Function(String url) onTap;

  const UpdatePrompt({required this.storeUrl, required this.onTap});
}

class DartNativeLicense {
  DartNativeLicense._();
  static final DartNativeLicense instance = DartNativeLicense._();

  UpdatePrompt? updatePrompt;

  LicensePayload? _cachedPayload;

  void provideToken(String token) { throw UnimplementedError(); }

  void noteTrialEnded() { throw UnimplementedError(); }

  void provideLicenseKey(String key) { throw UnimplementedError(); }

  String? get currentLaunchToken { throw UnimplementedError(); }

  bool get needsKeyActivation { throw UnimplementedError(); }

  bool get activationPending { throw UnimplementedError(); }

  Future<void>? get exchangeInFlight { throw UnimplementedError(); }

  String? activateWithKey({String? apiBase, String? installDir}) { throw UnimplementedError(); }

  static String computeMachineFingerprint() { throw UnimplementedError(); }

  void validate() { throw UnimplementedError(); }

  Future<void> activateFromServer(String licenseKey, {String? apiBase}) { throw UnimplementedError(); }

  Future<void> launchCheck(
    String licenseKey, {
    required String appId,
    String? apiBase,
    String? installId,
    String? installDir,
  }) { throw UnimplementedError(); }

  Future<void> launchCheckInBackground(
    String licenseKey, {
    required String appId,
    String? apiBase,
    String? installId,
    String? installDir,
  }) { throw UnimplementedError(); }

  String? appIdOwnedElsewhere({String? installDir}) { throw UnimplementedError(); }

  static const int _kMaxUnverifiedUseDays = 30;

  static String? get appBundleId { throw UnimplementedError(); }

  void validatePlugin(String pluginId) { throw UnimplementedError(); }

  void reportPluginUsage(Iterable<String> pluginIds) { throw UnimplementedError(); }

  LicenseStatus get status { throw UnimplementedError(); }

  LicensePayload? get payload { throw UnimplementedError(); }

  void reset() { throw UnimplementedError(); }

