class NavigatorObserver {}

/// Flutter-compatible instance facade returned by [Navigator.of].
///
/// Methods forward to the existing static [Navigator] APIs.
class NavigatorState {
  final BuildContext _context;

  const NavigatorState._(this._context);

  Future<T?> push<T>(Route route) { throw UnimplementedError(); }

  void pop<T extends Object?>([T? result]) { throw UnimplementedError(); }

  void popUntil(bool Function(Route) predicate) { throw UnimplementedError(); }

  Future<T?> pushReplacement<T, TO extends Object?>(
    Route route, {
    TO? result,
  }) { throw UnimplementedError(); }

  Future<T?> pushNamed<T>(String routeName) { throw UnimplementedError(); }

  bool canPop() { throw UnimplementedError(); }
}

abstract class Navigator {
  /// Flutter-compatible lookup that returns an instance facade.
  static NavigatorState of(BuildContext context) { throw UnimplementedError(); }

  /// Push a new screen with native animation.
  ///
  /// The transition animation is controlled by [PageRoute.transition]:
  /// ```dart
  /// Navigator.push(context, PageRoute(
  ///   builder: (_) => const MyScreen(),
  ///   transition: RouteTransition.slideFromBottom, // modal style
  /// ));
  /// ```
  static Future<T?> push<T>(BuildContext context, Route route) { throw UnimplementedError(); }

  static void pop(BuildContext context, [dynamic result]) { throw UnimplementedError(); }

  /// Pop screens until [predicate] returns true.
  ///
  /// The predicate receives a [Route] for each entry. Use [ModalRoute.withName]
  /// for name-based matching, or `(route) => route.isFirst` to pop to root.
  ///
  /// Example:
  /// ```dart
  /// Navigator.popUntil(context, (route) => route.isFirst);
  /// Navigator.popUntil(context, ModalRoute.withName('/home'));
  /// ```
  static void popUntil(BuildContext context, bool Function(Route) predicate) { throw UnimplementedError(); }

  /// Replace the current screen with a new one.
  static Future<T?> pushReplacement<T, TO extends Object?>(
    BuildContext context,
    Route route, {
    TO? result,
  }) { throw UnimplementedError(); }

  static Future<T?> pushNamed<T>(BuildContext context, String routeName) { throw UnimplementedError(); }

  static bool canPop(BuildContext context) { throw UnimplementedError(); }
}

/// Present the native modal sheet — the system's detent-height card with a
/// dimmed background — hosting dartnative widgets.
///
/// iOS 15+: backed by `UISheetPresentationController` — native spring
/// physics, a drag handle (when [showDragHandle] is true), and
/// swipe-to-dismiss. iOS 14 falls back to `.pageSheet` presentation (same
/// appearance, minus the advanced detent controls). Android: Material's
/// modal bottom sheet resting at the detent, half height for `medium` and
/// `adaptive` (draggable to full), full height below the status bar for
/// `large`, with the content laid out at the sheet's height; `fitContent`
/// is the same host sized to its content.
///
/// The [builder] receives a [BuildContext] and returns the sheet's content.
/// Any dartnative widget can be used inside: `Text`, `TextField`, `Column`,
/// `Container`, etc.
///
/// `Navigator.pop(context)` from inside the sheet dismisses it and completes
/// the returned [Future] with [result].
///
/// ```dart
/// final result = await showModalSheet<String>(
///   context: context,
///   detent: SheetDetent.large,
///   builder: (_) => const MySheetContent(),
/// );
/// ```
///
/// Parameters:
/// - [detent]          Height preset — [SheetDetent.medium], [SheetDetent.large]
///                     (default), or [SheetDetent.adaptive] (medium → draggable to large)
/// - [backgroundColor] Sheet background color; null = system default
///                     (`UIColor.systemBackground`)
/// - [cornerRadius]    Corner radius in points; -1 = system default (~13 pt on iOS 15)
/// - [showDragHandle]  Show the drag indicator at the top of the sheet (iOS 15+).
///                     Same name and default as Flutter's sheet param: off,
///                     as a UIKit or SwiftUI sheet with one detent shows none.
/// The sheet's declared header: a centered [title], a leading [close]
/// button and a trailing [action] button — the pattern of the system's
/// sheet editors (Close on the leading edge, a prominent Done trailing).
///
/// Declare it; the framework renders it. The header lowers to standalone
/// system glass buttons composed above the sheet content ([close] as a
/// glass capsule, [action] as the prominent tinted capsule when
/// [BarButtonItem.prominent] is set — tint from its `titleStyle` color).
/// Icons are SF Symbol names via [BarButtonItem.icon]; `onPressed` fires
/// on tap — dismiss the sheet from it with
/// `Navigator.pop(context, result)`.
class SheetHeader {
  final String? title;
  final BarButtonItem? close;
  final BarButtonItem? action;

  /// Trailing actions, leading to trailing; the last is the trailing-most.
  /// At most two [BarButtonItem]s. On the system-bar path ADJACENT items
  /// share one glass capsule, Apple's own pairing; a `SizedBox(width:)`
  /// between them lowers to a fixed space and splits them into their own
  /// capsules, the same convention as `AppBar.actions`. Composed, each
  /// action renders as its own glass button either way. Supersedes
  /// [action] when set.
  final List<Widget>? actions;

  /// REAL bar items on the sheet's own navigation bar, the default on
  /// iOS: the system lays the header out (safe areas, landscape cutouts),
  /// adjacent trailing actions share one glass capsule with the system
  /// press, and the title centres natively. Set false to compose glass
  /// buttons above the content instead. No effect on Android or on
  /// fitContent sheets, which lower to the bottom overlay and always
  /// compose.
  final bool systemBar;

  const SheetHeader({
    this.title,
    this.close,
    this.action,
    this.actions,
    this.systemBar = true,
  });

  /// The trailing [BarButtonItem]s, whichever field declared them.
  List<BarButtonItem> get trailingItems { throw UnimplementedError(); }

  /// The fixed space declared between two trailing actions, 0 when they
  /// are adjacent (= one shared capsule on the system-bar path).
  double get trailingGap { throw UnimplementedError(); }
}

/// Re-configures a live sheet's header, for headers that change with the
/// sheet's state (an edit toggle, a copied tick). On the system-bar path
/// each [update] re-lowers the bar items once [showModalSheet] has armed
/// it; on the composed paths, Android and the iOS 26 fitContent lowering,
/// the composed header row follows [current]. A header declared from the
/// content's initState is kept and shown as the sheet appears.
class SheetHeaderController {

  /// The header last declared through [update], if any.
  SheetHeader? get current { throw UnimplementedError(); }

  void update(SheetHeader header) { throw UnimplementedError(); }

}

/// The composed header row above a sheet's content, for the paths without
/// a navigation bar to host items. With a [controller] the row follows
/// the header the content declares, from its initState on; without one
/// the static [header] is composed once.
class _SheetHeaderHost extends StatefulWidget {
  const _SheetHeaderHost({
    this.header,
    this.controller,
    required this.fill,
    this.surface,
    required this.child,
  });

  final SheetHeader? header;
  final SheetHeaderController? controller;

  /// The sheet's colour, which the Android capsules lift for their fill.
  final Color? surface;

  /// True in a sheet whose height is the detent's: the content takes the
  /// room below the header, as it does below the bar on the bar-item path.
  /// False in a content-fit sheet, whose height is the content's.
  final bool fill;
  final Widget child;

  @override
  State<_SheetHeaderHost> createState() { throw UnimplementedError(); }
}

class _SheetHeaderHostState extends State<_SheetHeaderHost> {

  @override
  void initState() { throw UnimplementedError(); }

  @override
  void dispose() { throw UnimplementedError(); }

  @override
  Widget build(BuildContext context) { throw UnimplementedError(); }
}
