/// Semantics, MergeSemantics and ExcludeSemantics — what screen readers say
/// about a widget.
library;

import '../core.dart';

/// Describes its child to screen readers, as Flutter's `Semantics`: VoiceOver
/// on iPhone and TalkBack on Android.
///
/// The child becomes one element, read as its [label] followed by the text
/// the child shows, then its [value] and [hint]. Use it to name a control
/// drawn from shapes and icons:
///
/// ```dart
/// Semantics(
///   label: 'Hold to delete',
///   button: true,
///   onLongPressHint: 'Delete record',
///   child: GestureDetector(onLongPress: deleteRecord, child: const DeleteCircle()),
/// )
/// ```
///
/// A double tap activates the element: it runs [onTap], or taps the child.
class Semantics extends Widget {
  /// The widget described.
  final Widget? child;

  final bool container;

  /// Whether the text the child shows is left out, so only this widget's
  /// own description is read.
  final bool excludeSemantics;

  /// Whether the element is enabled; false reads it as dimmed (iPhone) or
  /// disabled (Android).
  final bool? enabled;

  /// Whether the element is selected, as a selected tab or chip.
  final bool? selected;

  /// Whether the element is a button.
  final bool? button;

  /// Whether the element is a link. On iPhone; Android reads it as text.
  final bool? link;

  /// Whether the element is a heading, which screen readers can jump
  /// between.
  final bool? header;

  /// Whether the element is an image.
  final bool? image;

  /// The element's name.
  final String? label;

  /// The element's value, as a percentage or a count.
  final String? value;

  /// What the element does, read after a pause.
  final String? hint;

  /// What a double tap does, read by TalkBack as "double-tap to …". On
  /// Android.
  final String? onTapHint;

  /// What a long press does: on iPhone an action in VoiceOver's actions
  /// list, on Android read by TalkBack as "double-tap and hold to …".
  final String? onLongPressHint;

  /// Runs when a screen reader activates the element, in place of a tap
  /// on the child.
  final VoidCallback? onTap;

  /// Runs when a screen reader long-presses the element, in place of a long
  /// press on the child.
  final VoidCallback? onLongPress;

  const Semantics({
    super.key,
    this.child,
    this.container = false,
    this.excludeSemantics = false,
    this.enabled,
    this.selected,
    this.button,
    this.link,
    this.header,
    this.image,
    this.label,
    this.value,
    this.hint,
    this.onTapHint,
    this.onLongPressHint,
    this.onTap,
    this.onLongPress,
  });
}

/// Reads its child as one element, as Flutter's `MergeSemantics`: the text
/// and the roles of everything in it together, so a row of a label and a
/// switch is one stop for VoiceOver and TalkBack. A double tap activates
/// the control in it.
class MergeSemantics extends Widget {
  /// The widget read as one element.
  final Widget? child;

  const MergeSemantics({super.key, this.child});
}

/// Hides its child from screen readers, as Flutter's `ExcludeSemantics`:
/// for a decoration, or text another element already reads.
class ExcludeSemantics extends Widget {
  /// Whether the child is hidden.
  final bool excluding;

  /// The widget hidden.
  final Widget? child;

  const ExcludeSemantics({super.key, this.excluding = true, this.child});
}

/// What a widget says about itself, under any [Semantics] around it: an
/// icon's or an image's label, a button's role. A [Semantics] around it
/// adds to it.
class OwnSemantics extends Semantics {
  const OwnSemantics({
    super.key,
    super.child,
    super.enabled,
    super.button,
    super.image,
    super.label,
  });
}
