  standard,

  memoryOnly,

  none,
}

class Image extends Widget {
  final ImageProvider image;
  final double? width;
  final double? height;
  final BoxFit? fit;
  final Color? color;
  final AlignmentGeometry alignment;

  final ImageCachePolicy cachePolicy;

  final Duration fadeInDuration;

  final Widget? placeholder;

  final Duration placeholderMinDuration;

  final Widget? errorWidget;

  final int? cacheWidth;
  final int? cacheHeight;

  final String? semanticLabel;

  final bool excludeFromSemantics;

  const Image({
    super.key,
    required this.image,
    this.width,
    this.height,
    this.fit,
    this.color,
    this.alignment = Alignment.center,
    this.cachePolicy = ImageCachePolicy.standard,
    this.fadeInDuration = Duration.zero,
    this.placeholder,
    this.placeholderMinDuration = Duration.zero,
    this.errorWidget,
    this.cacheWidth,
    this.cacheHeight,
    this.semanticLabel,
    this.excludeFromSemantics = false,
  });

  factory Image.network(
    String url, {
    Key? key,
    double? width,
    double? height,
    BoxFit? fit,
    AlignmentGeometry alignment = Alignment.center,
    ImageCachePolicy cachePolicy = ImageCachePolicy.standard,
    Duration fadeInDuration = Duration.zero,
    Widget? placeholder,
    Duration placeholderMinDuration = Duration.zero,
    Widget? errorWidget,
    int? cacheWidth,
    int? cacheHeight,
    String? semanticLabel,
    bool excludeFromSemantics = false,
    Map<String, String>? headers,
  }) { throw UnimplementedError(); }

  factory Image.asset(
    String name, {
    Key? key,
    double? width,
    double? height,
    BoxFit? fit,
    Color? color,
    AlignmentGeometry alignment = Alignment.center,
    int? cacheWidth,
    int? cacheHeight,
    String? semanticLabel,
    bool excludeFromSemantics = false,
  }) { throw UnimplementedError(); }

  factory Image.file(
    File file, {
    Key? key,
    double? width,
    double? height,
    BoxFit? fit,
    int? cacheWidth,
    int? cacheHeight,
    String? semanticLabel,
    bool excludeFromSemantics = false,
  }) { throw UnimplementedError(); }

  factory Image.memory(
    Uint8List bytes, {
    Key? key,
    double? width,
    double? height,
    BoxFit? fit,
    int? cacheWidth,
    int? cacheHeight,
    String? semanticLabel,
    bool excludeFromSemantics = false,
  }) { throw UnimplementedError(); }
