<script type="text/x-dc" data-dc-script data-props='{"$preview":{"width":390,"height":844}}'>
class Component extends DCLogic {
renderVals() {
const base = [
{ id: 'jacket', title: 'Organic Cotton Jacket', variant: 'Size: S', price: 120, img: '../img/u2.jpg' },
{ id: 'sweater', title: 'Cotton Sweater', variant: 'Size: M', price: 45, img: '../img/k3.jpg' },
{ id: 'sneaker', title: 'Classic Beige Low-Top Sneaker', variant: 'Size: 9', price: 120, img: '../img/f4.jpg' }
];
const qty = (this.state && this.state.qty) || { jacket: 1, sweater: 1, sneaker: 1 };
const money = (n) => '$' + n.toFixed(2);
const set = (id, n) => this.setState({ qty: { ...qty, [id]: Math.max(0, n) } });
const lines = base.filter((b) => qty[b.id] > 0).map((b) => ({
...b,
qty: qty[b.id],
total: money(b.price * qty[b.id]),
inc: () => set(b.id, qty[b.id] + 1),
dec: () => set(b.id, qty[b.id] - 1)
}));
const count = lines.reduce((a, l) => a + l.qty, 0);
return {
lines,
count,
hasItems: count > 0,
subtotal: money(lines.reduce((a, l) => a + l.price * l.qty, 0))
};
}
}
</script>
