                                          : AppColors.dotInactive,
                                    ),
                                  ),
                                ),
                              ),
                          ],
                        ),
                      ),
                    ),
                ],
              ),
      ),
    );
  }

  Widget _optionRow(ProductDetail product, ProductOption option) {
    final selected = _variant?.selectedOptions[option.name] ?? '';
