            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    product.title,
                    style: const TextStyle(
                      fontSize: 15,
                      height: 20 / 15,
                      color: AppColors.text,
                    ),
                  ),
                  const SizedBox(height: 4),
                  PriceLine(
                    price: product.price,
                    compareAt: product.saleCompareAt,
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
